// === BFS LEVEL-ORDER (pointer-based, no shift) ===
function bfsLevelOrder(graph, start) {
  const visited = new Set([start]);
  const queue = [start];
  let head = 0, level = 0;

  while (head < queue.length) {
    const levelSize = queue.length - head; // nodes at current level
    for (let i = 0; i < levelSize; i++) {
      const node = queue[head++];
      // process node here
      for (const neighbor of (graph[node] || [])) {
        if (!visited.has(neighbor)) {
          visited.add(neighbor); // mark before enqueue, not after dequeue
          queue.push(neighbor);
        }
      }
    }
    level++;
  }
}

// === MONOTONIC DEQUE (sliding window maximum) ===
function slidingWindowMax(arr, k) {
  const deque = []; // stores indices; front = max of current window
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    // remove indices outside the window
    if (deque.length && deque[0] <= i - k) deque.shift();
    // remove indices whose values are dominated by current element
    while (deque.length && arr[deque[deque.length - 1]] < arr[i]) deque.pop();
    deque.push(i);
    // window is fully formed starting at index k-1
    if (i >= k - 1) result.push(arr[deque[0]]);
  }
  return result;
}
